  function audio(id) {
    if(muted) return;
    try {
      const Context = window.AudioContext || window.webkitAudioContext;
      if(!Context) return;
      audioCtx ??= new Context();
      if(audioCtx.state === 'suspended') audioCtx.resume().catch(()=>{});
      const start=audioCtx.currentTime;
      const notes=id==='duck'?[410,300]:id==='black'?[610,780]:id==='panda'?[355,385]:[470,450];
      notes.forEach((hz,i)=>{
        const oscillator=audioCtx.createOscillator(),gain=audioCtx.createGain();
        oscillator.type=id==='duck'?'triangle':'sine';
        oscillator.frequency.setValueAtTime(hz,start+i*.075);
        oscillator.frequency.exponentialRampToValueAtTime(hz*.83,start+i*.075+.115);
        gain.gain.setValueAtTime(.0001,start+i*.075);
        gain.gain.exponentialRampToValueAtTime(.024,start+i*.075+.014);
        gain.gain.exponentialRampToValueAtTime(.0001,start+i*.075+.145);
        oscillator.connect(gain);gain.connect(audioCtx.destination);
        oscillator.start(start+i*.075);oscillator.stop(start+i*.075+.155);
      });
    } catch {}
  }

  const footer = document.querySelector('footer .footer-bottom') || document.querySelector('footer');
